const webhookData = $input.first();
const body = webhookData.json.body || {};

// Ambil data dari Kirimi
const userMessage = body.message || "";
const messageType = body.messageType || "";
const userNumber = body.from || "unknown";  // ← TIDAK strip @lid, passthrough as-is
const _isLid    = String(userNumber).toLowerCase().includes('@lid');
const userLid   = String(body.originLid || (_isLid ? userNumber : '')).replace(/\D/g, '');// kunci cocok
const userPhone = _isLid ? '' : String(userNumber).replace(/\D/g, '');// utk kolom No WA
const userName = body.name || body.pushName || body.notifyName || "User";
const isFromMe = body.isFromMe === true;
const eventType = body.event || "";

// Filter: hanya pesan teks yang tidak kosong
if (messageType !== "text" || !userMessage || userMessage.trim() === "") {
    console.log('⛔ STOP: Bukan pesan teks valid');
    return [];
}

console.log('✅ LANJUT: Pesan teks valid dari user');
console.log('📱 No WA:', userNumber);

// Counter sederhana
let counter = $vars.chatCounter || 0;
counter++;
$vars.chatCounter = counter;

// Format tanggal & jam WIB
const now = new Date();
const formattedDate = now.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});
const formattedTime = now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
}).replace(/\./g, ':');

const processStartTs = Date.now();

const aiInputText = `[SYSTEM_DATA]
CHAT_COUNTER: ${counter}
USER_NAME: ${userName}
USER_MESSAGE: "${userMessage}"

[USER QUERY]
${userMessage}`;

return [{
    json: {
        chat_counter: counter,
        user_wa: userNumber,
        user_lid: userLid,
        user_phone: userPhone,
        user_name: userName,
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        ai_input_text: aiInputText,
        original_message: userMessage,
        body: body,
        message_type: messageType,
        process_start_ts: processStartTs
    }
}];

// ====================================================================
// PROCESS COUNTER & MERGE DATA (V4)
// Fix: (1) matching row No WA primer / lid backup (bukan lid-only),
//      (2) "Tanggal Chat Pertama" dibaca dari kolom yang benar
//          (dulu baca existingRow.Tanggal yang tidak ada -> tanggal
//          pertama ter-reset jadi hari ini setiap pesan),
//      (3) error -> stop (return []) alih-alih menulis row "ERROR".
// ====================================================================
const debugLog = [];

try {
    const allItems = $input.all();
    debugLog.push("Step 1: Received " + allItems.length + " items from Read STATS");

    const chatCounter = $('Chat Counter').first().json;
    const resolve = $('Resolve User Row').first().json;
    const resolvedKey = resolve.resolved_key;

    const userName = chatCounter.user_name || "User";
    const userMessage = chatCounter.original_message || "";
    const digits = v => String(v ?? '').replace(/\D/g, '');
    const phone = digits(chatCounter.user_phone);
    const lid = digits(chatCounter.user_lid);

    if (!resolvedKey) {
        console.warn("resolved_key kosong - skip update STATS");
        return [];
    }

    // Process sheet rows
    const sheetRows = allItems
        .filter(item => {
            const data = item?.json || item;
            if (!data || Object.keys(data).length === 0) return false;
            return !!(data['lid'] || data['No WA'] || data.no_wa || data.NoWA);
        })
        .map(item => item?.json || item);

    debugLog.push("Step 2: Sheet rows found: " + sheetRows.length);

    // Find existing row: No WA primer, lid backup (konsisten dgn Resolve User Row)
    let existingRow = null;
    if (phone) existingRow = sheetRows.find(r => digits(r['No WA']) === phone) || null;
    if (!existingRow && lid) {
        existingRow = sheetRows.find(r => digits(r['lid']) === lid)
                   || sheetRows.find(r => digits(r['No WA']) === lid)
                   || null;
    }

    const isNewUser = !existingRow;
    debugLog.push("Step 3: " + (isNewUser ? "NEW USER" : "EXISTING USER"));

    let counter, pesanPertama, tanggalPertama, intensitasChat;

    if (existingRow) {
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;

        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && String(pesanLama).trim() !== '') ? pesanLama : userMessage;

        // V4 FIX: baca kolom yang benar
        const tglLama = existingRow['Tanggal Chat Pertama'];
        tanggalPertama = (tglLama && String(tglLama).trim() !== '') ? tglLama : null;
    } else {
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;
    }

    if (!tanggalPertama) {
        tanggalPertama = new Date().toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
        });
    }

    const outputData = {
        "No WA": resolvedKey,
        "lid": lid,
        "Tanggal": tanggalPertama,
        "TanggalSekarang": new Date().toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
        }),
        "Nama": userName,
        "Pesan Pertama": pesanPertama,
        "Counter": counter,
        "Intensitas Chat": intensitasChat
    };

    return [{ json: outputData }];

} catch (error) {
    // V4 FIX: jangan menulis row "ERROR" ke sheet - cukup log & stop.
    console.error("Process Counter ERROR: " + error.message, debugLog);
    return [];
}

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.original_message;   // ← perbaikan utama

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// ============================================================
// Send WA + Verify (Kirimi)
// Gabungan node lama: "Reply Chat Kirimi" (HTTP Request) + "Check API Response" (Code).
//
// KENAPA DIGABUNG:
// n8n me-retry MULAI DARI node yang gagal (runData node sebelumnya dipertahankan).
// Kalau validasi berdiri sendiri sebagai node terpisah, klik Retry hanya mengulang
// validasi dengan respons Kirimi yang lama -> throw lagi -> WA tidak pernah
// terkirim ulang. Dengan digabung, satu klik Retry benar-benar mengirim ulang.
//
// On Error = Stop Workflow (sengaja, jangan diubah): supaya execution jadi merah,
// Error Notifier jalan, dan execution bisa di-retry dari mobile dashboard.
//
// Retry HTTP ditangani DI DALAM kode ini (3x, jeda 5 detik) supaya persis meniru
// perilaku lama node "Reply Chat Kirimi" (retryOnFail: true, waitBetweenTries: 5000).
// Retry TIDAK berlaku untuk kegagalan "HTTP 200 tapi status:false" -- sama seperti
// node "Check API Response" lama yang tidak punya retryOnFail. Ini disengaja:
// respons status:false berarti Kirimi sudah memproses permintaan, jadi mengirim
// ulang otomatis berisiko pesan dobel. Kirim ulang untuk kasus itu = keputusan
// manusia, lewat tombol Retry.
// ============================================================

const KIRIMI_URL = 'https://api.kirimi.id/v1/send-message';
const TIMEOUT_MS = 60000;
const MAX_HTTP_ATTEMPTS = 3;
const WAIT_MS = 5000;

const sleep = (ms) => new Promise((resolve) => {
  if (typeof setTimeout === 'function') { setTimeout(resolve, ms); } else { resolve(); }
});

// --- kredensial: literal, sama persis dengan node HTTP lama ---
const cfg = {
  user_code: 'KM40LI0426',
  secret: 'REDACTED',
  device_id: 'D-4ZV1F',
};

const phone = $('Chat Counter').first().json.user_wa;
const message = $('Process All').first().json.cleanOutput;

if (!phone) {
  throw new Error('Kirimi: nomor tujuan kosong (Chat Counter.user_wa)');
}
if (message === undefined || message === null || String(message).trim() === '') {
  throw new Error('Kirimi: pesan kosong (Process All.cleanOutput)');
}
if (!cfg.user_code || !cfg.secret || !cfg.device_id) {
  throw new Error('Kirimi: kredensial tidak lengkap (user_code/secret/device_id)');
}

// ---- 1) KIRIM (dengan retry khusus kegagalan HTTP) ----
let responseData = null;
let lastErr = null;

for (let attempt = 1; attempt <= MAX_HTTP_ATTEMPTS; attempt++) {
  try {
    responseData = await this.helpers.httpRequest({
      method: 'POST',
      url: KIRIMI_URL,
      body: {
        user_code: cfg.user_code,
        secret: cfg.secret,
        device_id: cfg.device_id,
        phone: phone,
        message: message,
      },
      json: true,
      timeout: TIMEOUT_MS,
    });
    lastErr = null;
    break;
  } catch (e) {
    lastErr = e;
    console.log('Kirimi HTTP gagal (percobaan ' + attempt + '/' + MAX_HTTP_ATTEMPTS + '): ' + (e && e.message ? e.message : String(e)));
    if (attempt < MAX_HTTP_ATTEMPTS) { await sleep(WAIT_MS); }
  }
}

if (lastErr) {
  throw new Error('Kirimi HTTP gagal setelah ' + MAX_HTTP_ATTEMPTS + ' percobaan: ' + (lastErr && lastErr.message ? lastErr.message : String(lastErr)));
}

// ---- 2) VERIFIKASI ISI RESPONS (logika lama "Check API Response") ----
const rd = (responseData && typeof responseData === 'object') ? responseData : {};
const explicitFail = rd.success === false || rd.status === false;
const isSuccess = !explicitFail && (
  rd.status === true ||
  rd.success === true ||
  (rd.data && rd.data.id) ||
  (rd.message && rd.message !== 'error')
);

if (!isSuccess) {
  throw new Error('Kirimi API gagal (HTTP 200 tapi respons menolak): ' + JSON.stringify(responseData));
}

console.log('Kirimi sukses:', JSON.stringify(responseData));
return [{ json: rd }];

// ============================================================
// HUMAN-IN-THE-LOOP CHECK (V4: No WA primer, lid backup)
// bot_mode = 'OFF' -> Sam handle manual -> stop.
// ============================================================
const cc = $('Chat Counter').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const phone = digits(cc.user_phone);
const lid = digits(cc.user_lid);

const statsRows = $('Read STATS for HITL').all()
  .map(r => r.json)
  .filter(r => r && Object.keys(r).length > 0);

let userRow = null;
if (phone) userRow = statsRows.find(r => digits(r['No WA']) === phone) || null;
if (!userRow && lid) {
  userRow = statsRows.find(r => digits(r['lid']) === lid)
         || statsRows.find(r => digits(r['No WA']) === lid)
         || null;
}

const botMode = userRow ? String(userRow['bot_mode'] || '').trim().toUpperCase() : '';

if (botMode === 'OFF') {
  console.log(`👨‍💼 HITL AKTIF — Sam sedang handle manual, bot berhenti.`);
  return [];
}

console.log(`🤖 Bot mode AKTIF (bot_mode="${botMode}") — lanjut.`);
return [$input.first()];

// ====================================================================
// NODE: Cek_user_status (V4)
// Peran: gate HITL post-debounce + gabung pesan MSG_BUFFER +
//        siapkan SYSTEM_DATA (intro user baru, kelas tersimpan).
// Alur status PARENT/STUDENT sudah DIHAPUS (register netral).
// ====================================================================
const cc = $('Chat Counter').first().json;
const resolve = $('Resolve User Row').first().json;
const resolvedKey = resolve.resolved_key;

// bot_mode dicek ulang SETELAH debounce (Wait 60 detik) —
// Sam bisa set OFF kapan saja selama bot menunggu.
const debounceItem = $('Re-Read STATS Debounce').first();
const debounceRow = (debounceItem && debounceItem.json) ? debounceItem.json : {};
const botModeNow = String(debounceRow['bot_mode'] || '').trim().toUpperCase();
if (botModeNow === 'OFF') {
  console.log('👨‍💼 HITL (post-debounce): bot_mode OFF — berhenti, Sam handle manual.');
  return [];
}

// ── Gabung pesan dari MSG_BUFFER (append-only, anti lost-update) ──
// Konsumsi: ts > buffer_done_ts (watermark) dan ts <= process_start_ts saya.
const doneTs = Number(debounceRow['buffer_done_ts'] || 0) || 0;
const myTs = Number(cc.process_start_ts) || 0;
let bufRows = [];
try {
  bufRows = $('Read MSG_BUFFER').all()
    .map(i => i.json)
    .filter(r => r && r.message !== undefined && r.message !== null);
} catch (e) {
  console.warn('⚠️ Read MSG_BUFFER tidak terbaca:', e.message);
}
// Batas kedaluwarsa: pesan lebih tua dari 30 menit tidak ikut digabung
// (mis. pesan yang sempat ter-buffer lalu ditangani manual oleh Sam saat bot OFF).
const MAX_AGE_MS = 30 * 60 * 1000;
const msgs = bufRows
  .map(r => ({ ts: Number(r.ts) || 0, message: String(r.message ?? '').trim() }))
  .filter(r => r.ts > doneTs && r.ts <= myTs && (myTs - r.ts) < MAX_AGE_MS && r.message !== '')
  .sort((a, b) => a.ts - b.ts)
  .map(r => r.message);

// Fallback aman: kalau buffer kosong (mis. append gagal), pakai pesan asli.
const userMessage = msgs.length ? msgs.join('\n') : (cc.original_message || '');
console.log(`📨 userMessage final ke AI (${msgs.length} pesan digabung):\n${userMessage}`);

// ── User baru? (greeting_sent belum Y) ──
const greetingSent = String(debounceRow['greeting_sent'] || resolve.greeting_sent || '').trim().toUpperCase();
const isNewUser = greetingSent !== 'Y';

// ── Fakta persisten (tahan restart n8n / reset memory) ──
// TTL 60 hari: kelas berubah tiap tahun ajaran, jangan injeksi data basi.
const KELAS_TTL_S = 60 * 86400;
const kelasTs = Number(debounceRow['kelas_anak_ts'] || resolve.kelas_anak_ts || 0) || 0;
const kelasFresh = kelasTs > 0 && (Math.floor(Date.now() / 1000) - kelasTs) <= KELAS_TTL_S;
const kelasAnak = kelasFresh ? String(debounceRow['kelas_anak'] || resolve.kelas_anak || '').trim() : '';
const programInterest = kelasFresh ? String(debounceRow['program_interest'] || resolve.program_interest || '').trim() : '';
if (kelasTs && !kelasFresh) console.log('⏳ kelas_anak kedaluwarsa (>60 hari) — tidak diinjeksi.');

const INTRO = 'Haloo thank you sudah contact TheScholars.id yaa. Saya Sam versi AI yaa, saya siap bantu untuk jawab pertanyaan yang ada mengenai program kita dan scholarships ke Singapore.';

// Tanggal hari ini (WIB) - WAJIB dikirim ke AI. Tanpa ini model menebak posisi waktu
// dan bisa salah menyimpulkan batch "belum dibuka" dari Tanggal Mulai yang masih di depan.
// Nama bulan dirakit manual supaya tidak bergantung ketersediaan locale id-ID di runtime.
const _BLN_ID = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const _wibNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const TANGGAL_HARI_INI = `${_wibNow.getDate()} ${_BLN_ID[_wibNow.getMonth()]} ${_wibNow.getFullYear()}`;

const aiSystemData = `[SYSTEM_DATA]
TANGGAL_HARI_INI: ${TANGGAL_HARI_INI} (WIB)
USER_WA: ${resolvedKey}
IS_NEW_USER: ${isNewUser}
KELAS_ANAK: ${kelasAnak || 'UNKNOWN'}
PROGRAM_INTEREST: ${programInterest || 'UNKNOWN'}

CRITICAL INSTRUCTION:
${isNewUser
  ? `USER BARU. Baris pertama balasan WAJIB intro ini PERSIS (jangan diubah/diringkas): "${INTRO}" Setelah intro, di pesan yang sama langsung jawab pertanyaan user kalau ada. Kalau user hanya menyapa, cukup intro saja.`
  : 'User lama. JANGAN kirim intro/perkenalan lagi, lanjutkan percakapan secara natural. Jangan reset percakapan dari awal.'}

[USER QUERY]
${userMessage}`;

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    ai_input_text: aiSystemData,
    user_message_final: userMessage,
    is_new_user: isNewUser,
    kelas_anak_db: kelasAnak,
    program_interest_db: programInterest,
    buffer_done_ts_old: doneTs
  }
}];

// ====================================================================
// UPDATE GREETING FLAG (V4 - disederhanakan)
// Dulu: pattern-matching teks balasan (rapuh, tergantung susunan
// kalimat). Sekarang: cukup dari flag is_new_user — kalau eksekusi
// ini mengirim intro ke user baru (reply sudah SUKSES terkirim
// karena node ini jalan setelah Reply Chat Kirimi), tandai Y.
// ====================================================================
const isNewUser = $('Cek_user_status').first().json.is_new_user === true;

if (isNewUser) {
  console.log('📝 [GREETING] intro terkirim ke user baru -> greeting_sent = Y');
}

return [{
  json: {
    update_needed: isNewUser ? 'true' : 'false',
    greeting_sent: 'Y'
  }
}];

// ============================================
// PREPROCESS - CONTEXT DETECTION (V4)
// - Deteksi status PARENT/STUDENT DIHAPUS (register netral).
// - Deteksi kelas MULTI-VALUE: bisa menangkap >1 kelas dalam satu
//   pesan (kasus orang tua dengan beberapa anak). Disimpan sebagai
//   daftar "SMP 1, SD 6".
// - Dukung jenjang Singapura/internasional (Primary/Sec) & angka
//   Romawi; fallback kelas tersimpan dari DB (kelas_anak, TTL di
//   Cek_user_status).
// ============================================

const json = $input.item.json;

// Get the full message (includes SYSTEM_DATA + user query)
const fullMessage = json.message || json.ai_input_text || json.text || json.body || '';

// ============================================
// 1. EXTRACT USER QUERY
// ============================================
let actualUserMessage = '';
if (fullMessage.includes('[USER QUERY]')) {
  const parts = fullMessage.split('[USER QUERY]');
  actualUserMessage = parts[1] ? parts[1].trim() : '';
} else {
  actualUserMessage = fullMessage.trim();
}

// ============================================
// 2. PARSE SYSTEM_DATA
// ============================================
let isNewUser = false;
let kelasAnakDB = '';
let programInterestDB = '';

if (fullMessage.includes('[SYSTEM_DATA]')) {
  const newUserMatch = fullMessage.match(/IS_NEW_USER:\s*(\w+)/i);
  if (newUserMatch) isNewUser = newUserMatch[1].toLowerCase() === 'true';

  const kelasMatch = fullMessage.match(/KELAS_ANAK:\s*([^\n]+)/i);
  if (kelasMatch) {
    const v = kelasMatch[1].trim();
    if (v && v.toUpperCase() !== 'UNKNOWN') kelasAnakDB = v;
  }
  const progMatch = fullMessage.match(/PROGRAM_INTEREST:\s*([^\n]+)/i);
  if (progMatch) {
    const v = progMatch[1].trim();
    if (v && v.toUpperCase() !== 'UNKNOWN') programInterestDB = v;
  }
}

// ============================================
// 3. PROCESS MESSAGE
// ============================================
const message = actualUserMessage.toLowerCase().replace(/\bkls\b/g, 'kelas').replace(/\bklas\b/g, 'kelas');
const userPhone = json.userPhone || json.from || json.phone || json.user_wa || 'unknown';

// ============================================
// 4. DETECT GRADE(S) & PROGRAM(S) — MULTI-VALUE
//    Semua pola discan (bukan berhenti di match pertama) supaya
//    ">1 anak" dalam satu pesan tertangkap semua.
//    Seniors KHUSUS kelas 12. SMA 10/11 -> belum ada program.
// ============================================
const GRADE_PATTERNS = [
  // Jenjang internasional/Singapura (intl=true)
  [/\b(?:primary|pri)\s*\.?\s*6\b|\bp6\b/i,        'SD 6',      'Junior',       true],
  [/\b(?:sec|secondary)\s*\.?\s*1\b/i,             'SMP 1',     'Junior',       true],
  [/\b(?:sec|secondary)\s*\.?\s*2\b/i,             'SMP 2',     'Intermediate', true],
  [/\b(?:sec|secondary)\s*\.?\s*3\b/i,             'SMP 3',     'Intermediate', true],
  [/\b(?:sec|secondary)\s*\.?\s*4\b/i,             'SMA 10/11', '',             true],
  // Angka Romawi (\b menjaga 'kelas x' tidak match di 'kelas xii')
  [/kelas\s*xii\b/i,                               'SMA 12',    'Seniors',      false],
  [/kelas\s*xi\b/i,                                'SMA 10/11', '',             false],
  [/kelas\s*x\b/i,                                 'SMA 10/11', '',             false],
  [/kelas\s*ix\b/i,                               'SMP 3',     'Intermediate', false],
  [/kelas\s*viii\b/i,                             'SMP 2',     'Intermediate', false],
  [/kelas\s*vii\b/i,                              'SMP 1',     'Junior',       false],
  [/kelas\s*vi\b/i,                               'SD 6',      'Junior',       false],
  // Pola Indonesia
  [/sd 6|kelas 6 sd|kelas 6(?!\s*smp)/i,           'SD 6',      'Junior',       false],
  [/smp 1|kelas 1 smp|kelas 7\b/i,                 'SMP 1',     'Junior',       false],
  [/smp 2|kelas 2 smp|kelas 8\b/i,                 'SMP 2',     'Intermediate', false],
  [/smp 3|kelas 3 smp|kelas 9\b/i,                 'SMP 3',     'Intermediate', false],
  [/sma 3|kelas 3 sma|kelas 12\b/i,                'SMA 12',    'Seniors',      false],
  [/sma 1|sma 2|kelas 1 sma|kelas 2 sma|kelas 10\b|kelas 11\b/i, 'SMA 10/11', '', false],
];

const PROGRAM_OF = { 'SD 6': 'Junior', 'SMP 1': 'Junior', 'SMP 2': 'Intermediate', 'SMP 3': 'Intermediate', 'SMA 12': 'Seniors', 'SMA 10/11': '' };

let grades = [];
let intlSystemDetected = false;
for (const [re, label, prog, intl] of GRADE_PATTERNS) {
  if (re.test(message) && !grades.includes(label)) {
    grades.push(label);
    if (intl) intlSystemDetected = true;
  }
}
// Fallback generik SMA (kelas belum jelas) hanya kalau tidak ada match lain
let smaUnclear = false;
if (!grades.length && message.match(/sma|kelas.*sma/i)) {
  smaUnclear = true;
}

// Fallback: kelas tersimpan dari percakapan sebelumnya (DB, sudah lolos TTL)
let gradeFromDB = false;
if (!grades.length && !smaUnclear && kelasAnakDB) {
  grades = kelasAnakDB.split(',').map(s => s.trim()).filter(Boolean);
  gradeFromDB = true;
}

const programs = [...new Set(grades.map(g => PROGRAM_OF[g] || '').filter(Boolean))];
const noProgramGrades = grades.filter(g => !(PROGRAM_OF[g] || ''));

// String gabungan (dipakai untuk penyimpanan kelas_anak & kompatibilitas)
const grade = grades.join(', ');
const recommendedProgram = gradeFromDB && programInterestDB ? programInterestDB : programs.join(', ');

// ============================================
// 5. DETECT REGISTRATION INTENT
// ============================================
const wantsToRegister = message.match(/daftar|mau ikut|tertarik|mau coba|mau daftar|link pendaftaran|link form|minta link/i) !== null;

// ============================================
// 5b. DETECT OUT-OF-SCOPE USER (di luar jenjang SMP-SMA)
// ============================================
let outOfScope = false;
if (message.match(/\b(mahasiswa|semester\s*\d+|lagi kuliah|sudah kuliah|udah kuliah|sarjana|magister|fresh graduate|gap year|karyawan|pegawai|sudah lulus|udah lulus|sudah kerja|udah kerja)\b/i)) {
  outOfScope = true;
}

// ============================================
// 5c. DETECT UNCLEAR / AMBIGUOUS SHORT REPLY (anti-loop)
// ============================================
const isGreetingLike = message.match(/^(hai|halo|hi|pagi|siang|sore|malam|makasih|thanks|terima kasih|ok|oke|sip|baik|👍|🙏)/i) !== null;
const unclearReply = (actualUserMessage.trim().length <= 4) && !grades.length && !isGreetingLike && !wantsToRegister;

// ============================================
// 6. DETECT PERSUASION TRIGGERS
// ============================================
let persuasionMode = '';
// PAYMENT dicek PALING DULU: intent transfer harus menang atas 'oke deh' (INTERESTED)
// dan 'nanti' (DEFER), spt pesan "oke deh mau transfer" / "udah tf, nanti kabarin yaa".
// Catatan: kata 'bayar'/'pembayaran' telanjang SENGAJA tidak dipakai sebagai pemicu -
// itu biasanya pertanyaan harga/cicilan yang MASIH BOLEH dijawab.
if (message.match(/\b(tf|trf|transfer|mau bayar|sudah bayar|udah bayar|sdh bayar|kirim bukti|bukti transfer|bukti bayar|bukti pembayaran|rekening|no rek|norek|nomor rekening|bayar ke ?mana|kirim ke ?mana|bayarnya ke ?mana)\b/i)) {
  persuasionMode = 'PAYMENT';
} else if (message.match(/mau daftar|tertarik|boleh deh|mau coba|mau ikut|oke deh/i)) {
  persuasionMode = 'INTERESTED';
} else if (message.match(/nanti (dulu|aja|saja|lah)|nanti deh|pikir dulu|pikir-?2? dulu|pikirkan dulu|dipikir dulu|setelah ujian|belum sekarang|belum kepikiran|masih ragu|\bragu\b|mikir (dulu|lagi)|lagi mikir|dipikir-?pikir|lihat dulu|liat dulu|tunggu dulu|nunggu dulu/i)) {
  // 'nanti' TELANJANG sengaja tidak dipakai: "nanti tolong kabarin", "nanti saya tanya lagi",
  // "nanti daftar" bukan penundaan, tapi dulu semuanya terbaca DEFER lalu AI diminta
  // 'singkat & jangan menekan' sehingga pertanyaan user malah tidak terjawab.
  persuasionMode = 'DEFER';
}

// ============================================
// 7. DETECT TOPICS
// ============================================
const discussingProgram = message.match(/program|junior|intermediate|senior|batch/i) !== null;
const askingPrice = message.match(/berapa|biaya|harga|bayar|mahal|murah/i) !== null;
const askingBatch = message.match(/batch|kapan|mulai|jadwal|pendaftaran/i) !== null;

// ============================================
// 8. BUILD AI CONTEXT
//    HANYA fakta deteksi + pointer, selaras system message.
// ============================================
let aiContext = '';

if (outOfScope) {
  aiContext += `User kemungkinan di luar jenjang SMP-SMA (mahasiswa/kuliah/kerja). Sampaikan jujur program khusus siswa SMP-SMA, jadi belum ada yang cocok. JANGAN tanya kelas SMP/SMA. `;
}

if (unclearReply) {
  aiContext += `Balasan user terlalu singkat/ambigu. JANGAN ulang pertanyaan yang sama. Kalau sebelumnya sudah bertanya hal yang sama, tawarkan bantuan langsung dari Sam: [TALK_TO_SAM]. `;
}

if (intlSystemDetected) {
  aiContext += `User menyebut jenjang sistem Singapura/internasional (Primary/Sec). Ini TIDAK berarti calon murid sudah bersekolah di Singapura, banyak sekolah kurikulum internasional di Indonesia. Jangan asumsikan lokasi sekolah, dan JANGAN tanya lokasi kecuali menentukan jawaban. `;
}

if (!outOfScope && grades.length) {
  const src = gradeFromDB ? 'SUDAH DIKETAHUI dari percakapan sebelumnya' : 'disebut di pesan ini';
  if (grades.length === 1) {
    const g = grades[0];
    const p = PROGRAM_OF[g] || '';
    if (p) {
      aiContext += `Kelas calon murid ${src}: ${g} -> arahkan ke program ${p}. ${gradeFromDB ? 'JANGAN tanya kelas lagi. ' : ''}Catatan: SMP 2 = Intermediate (BUKAN Junior). Sebut HANYA program ${p}, jangan tawarkan tier program lain kecuali user tanya. `;
    } else if (g === 'SMA 10/11') {
      aiContext += `Calon murid di SMA kelas 10/11 -> belum ada program yang cocok untuk sekarang (Seniors khusus kelas 12). Sampaikan jujur dan arahkan ke opsi yang ada.${gradeFromDB ? ' Kelas sudah diketahui, JANGAN tanya kelas lagi.' : ''} `;
    }
  } else {
    // Multi-anak: sebutkan pemetaan per kelas
    const mapText = grades.map(g => `${g} -> ${PROGRAM_OF[g] || 'belum ada program yang cocok (Seniors khusus kelas 12)'}`).join('; ');
    aiContext += `User menyebut LEBIH DARI SATU kelas calon murid (kemungkinan beberapa anak), ${src}: ${mapText}. JANGAN tanya ulang kelas. Bahas program sesuai kelas masing-masing, ringkas, tanpa membandingkan tier lain di luar itu. Catatan: SMP 2 = Intermediate (BUKAN Junior). `;
  }
} else if (smaUnclear) {
  aiContext += `Calon murid SMA tapi kelas belum jelas -> tanya dulu kelas berapa (Seniors hanya untuk kelas 12). `;
}

if (wantsToRegister) {
  aiContext += `User ingin daftar -> siapkan [SEND_GFORM] HANYA jika diizinkan ATURAN BATCH (batch reguler DIBUKA, atau Mock Interview, atau Seniors). Kalau batch belum dibuka, arahkan user menunggu kabar pendaftaran. `;
}

if (persuasionMode) {
  if (persuasionMode === 'INTERESTED') {
    aiContext += `User tertarik daftar. Ikuti ATURAN BATCH. Nada tenang dan netral, langsung ke langkah daftar tanpa berlebihan. `;
  } else if (persuasionMode === 'DEFER') {
    aiContext += `User menunda. Validasi singkat dan santai, beri ruang tanpa menekan waktu. `;
  } else if (persuasionMode === 'PAYMENT') {
    aiContext += `User menyinggung pembayaran/transfer. PEMBAYARAN DITANGANI SAM MANUAL, bukan kamu. Balas PERSIS: "Baik, nanti akan dibantu cek dengan Sam yaa." lalu berhenti. DILARANG menyebut transfer/tf/rekening/bukti bayar, dilarang minta bukti, dilarang konfirmasi pembayaran diterima, dilarang pasang tag [TALK_TO_SAM]. `;
  }
}

// ============================================
// 9. BUILD ENHANCED INPUT FOR AI
// ============================================
// FIX C1: preserve the [SYSTEM_DATA] block from Cek_user_status so
// IS_NEW_USER + intro instruction survive to the AI Agent. Detection
// facts are added as an extra [CONTEXT: ...] block.
let systemDataBlock = '';
if (fullMessage.includes('[USER QUERY]')) {
  systemDataBlock = fullMessage.split('[USER QUERY]')[0].trim();
}
let enhancedInput = '';
if (systemDataBlock) enhancedInput += systemDataBlock + `\n\n`;
if (aiContext.trim()) enhancedInput += `[CONTEXT: ${aiContext.trim()}]\n\n`;
enhancedInput += `[USER QUERY]\n${actualUserMessage}`;

// ============================================
// OUTPUT
// ============================================
return {
  userPhone,
  actualUserMessage,
  fullMessage,
  messageLower: message,
  isNewUser,
  kelasAnakDB,
  programInterestDB,
  grade,
  grades,
  gradeFromDB,
  intlSystemDetected,
  recommendedProgram,
  wantsToRegister,
  discussingProgram,
  askingPrice,
  askingBatch,
  persuasionMode,
  outOfScope,
  unclearReply,
  aiContext: aiContext.trim(),
  ai_input_text: enhancedInput
};

// ===== CONTEXT RETRIEVE V3 (KONSOLIDASI) =====
// Single source of truth = tab PROGRAM (superset: harga, batch, status, syarat).
// + ABOUT_SAM (bio) + LINKS (url) + FAQ. Token-efisien, anti-halu, tanpa tool agent.
try {
  const pre = $('Preprocess - Context Detection').first().json;
  const query = pre.actualUserMessage || '';
  const flags = {
    askingPrice: !!pre.askingPrice,
    askingBatch: !!pre.askingBatch,
    discussingProgram: !!pre.discussingProgram,
    wantsToRegister: !!pre.wantsToRegister,
  };
  const askingSyarat = /syarat|persyaratan|kriteria|ketentuan|dokumen|rapor|raport|portofolio|portfolio|requirement|nilai|esai|essay/i.test(query);
  const askingAboutSam = /\bsam\b|founder|pendiri|pengajar|mentor|tutor|guru|ngajar|siapa kak|siapa ini|admin|alumni|lulus|sekolah.*(mana|sg|singap)|kuliah|background|pengalaman|kerja/i.test(query);
  const askingProgramDetail = flags.discussingProgram || !!pre.grade || /durasi|berapa kali|seminggu|format|online|sesi|materi|isi program|belajar apa/i.test(query);

  // Kegagalan baca sheet dicatat, TIDAK ditelan diam-diam. Versi lama mengembalikan []
  // tanpa log, sehingga "sheet gagal dibaca" tidak bisa dibedakan dari "sheet memang
  // kosong" - VIRA lalu melayani customer seolah The Scholars tidak punya program.
  const sheetIssues = [];
  // Ringkasan per node ikut ke OUTPUT node (bukan cuma console), supaya bisa
  // dibaca langsung dari execution data tanpa membuka panel Logs n8n.
  const sheetDebug = {};
  const grab = (node) => {
    // pull(true) memaksa baca hasil run pertama. Perlu karena Read PROGRAM/ABOUT/LINKS
    // ber-executeOnce: kalau node ini jalan di run kedua (debounce/buffer), referensi
    // run saat ini kosong walau datanya sebenarnya sudah terambil di run pertama.
    const pull = (useFirstRun) => {
      try {
        const ref = $(node);
        const items = useFirstRun ? ref.all(0, 0) : ref.all();
        return (items || []).map(i => i.json).filter(Boolean);
      } catch (e) {
        return { err: (e && e.message) ? e.message : String(e) };
      }
    };

    const rows = pull(false);

    if (rows && rows.err !== undefined) {
      const first = pull(true);
      if (first && first.err === undefined && first.length) {
        console.warn('SHEET PULIH: "' + node + '" gagal di run saat ini (' + rows.err + '), diambil dari run pertama. ' + first.length + ' baris.');
        sheetDebug[node] = first.length + ' baris — FALLBACK run pertama (run saat ini error: ' + rows.err + ')';
        return first;
      }
      console.error('SHEET GAGAL DIBACA: "' + node + '" -> ' + rows.err);
      sheetIssues.push(node + ' (error: ' + rows.err + ')');
      sheetDebug[node] = 'GAGAL — ' + rows.err;
      return [];
    }

    if (!rows.length) {
      const first = pull(true);
      if (first && first.err === undefined && first.length) {
        console.warn('SHEET PULIH: "' + node + '" kosong di run saat ini, diambil dari run pertama. ' + first.length + ' baris.');
        sheetDebug[node] = first.length + ' baris — FALLBACK run pertama (run saat ini 0 baris)';
        return first;
      }
      console.error('SHEET KOSONG: "' + node + '" tidak mengembalikan baris apa pun.');
      sheetIssues.push(node + ' (0 baris)');
      sheetDebug[node] = '0 baris — KOSONG';
      return [];
    }

    sheetDebug[node] = rows.length + ' baris — normal';
    return rows;
  };
  const val = (row, ...keys) => { for (const k of keys) { for (const rk of Object.keys(row)) { if (rk.toLowerCase().trim() === k.toLowerCase().trim() || rk.toLowerCase().startsWith(k.toLowerCase())) { const v = row[rk]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } } } return ''; };
  const clip = (s, n) => { s = (s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };

  const parts = [];
  const prog = grab('Read PROGRAM Data');

  // Database tidak terbaca = GANGGUAN SISTEM, bukan "programnya tidak ada".
  // Tanpa penanda ini AI menyimpulkan The Scholars tidak punya program apa pun dan
  // menjawab dengan yakin - persis kegagalan yang terlihat di produksi.
  if (!prog.length) {
    parts.push('PERINGATAN SISTEM: DATABASE PROGRAM TIDAK TERBACA untuk pesan ini. Ini gangguan teknis, BUKAN berarti programnya tidak ada. DILARANG menyatakan program/batch tidak ada, dan DILARANG menyebut status pendaftaran, harga, jadwal, atau kuota. Untuk semua pertanyaan soal program, batch, harga, jadwal, dan pendaftaran -> jawab [UNKNOWN]. Jangan sebut adanya gangguan sistem ke user.');
  }

  // STATUS & BATCH (selalu; gating harga & pendaftaran) -- diturunkan dari PROGRAM
  // Kolom "Status" adalah SATU-SATUNYA penentu pendaftaran buka/tutup. Verdict dihitung
  // di sini (deterministik) supaya AI tidak menyimpulkannya sendiri dari tanggal.
  if (prog.length) {
    // Dropdown kolom Status di sheet PROGRAM: Active | Coming Soon | Closed | Always Active.
    // Dicocokkan per KATA supaya varian ejaan tetap kena. Urutan pemeriksaan penting:
    // ALWAYS dulu (mengandung "Active"), lalu SOON/CLOSED (mengandung "belum"/"tutup"),
    // baru OPEN. Kalau OPEN dicek duluan, "Coming Soon"/"Belum dibuka" salah terbaca.
    const ALWAYS_RE = /always|selalu/i;
    const SOON_RE = /(coming\s*soon|belum\s*dibuka|belum\s*buka|akan\s*datang)/i;
    const CLOSED_RE = /(closed|close|tutup|ditutup|penuh|full|selesai|inactive|tidak\s*aktif|non\s*-?\s*aktif)/i;
    const OPEN_RE = /(active|aktif|open|buka|dibuka|berjalan|ongoing)/i;

    // "hari ini" WIB, dinormalkan ke tengah malam supaya deadline hari-H tetap dihitung berlaku
    const _nowWib = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
    const todayWib = new Date(_nowWib.getFullYear(), _nowWib.getMonth(), _nowWib.getDate());
    const BLN_ID = ['januari','februari','maret','april','mei','juni','juli','agustus','september','oktober','november','desember'];
    const parseTglID = (s) => {
      const m = String(s || '').match(/(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})/);
      if (!m) return null;
      const bi = BLN_ID.indexOf(m[2].toLowerCase());
      return bi === -1 ? null : new Date(Number(m[3]), bi, Number(m[1]));
    };

    const lines = prog.map(r => {
      const nm = val(r, 'Nama Program'), st = val(r, 'Status'), batch = val(r, 'Nama Batch');
      const mulai = val(r, 'Tanggal Mulai'), dl = val(r, 'Deadline Daftar'), kuota = val(r, 'Kuota');
      const hasBatch = batch && batch !== '-';
      const stRaw = String(st || '').trim();
      const dlDate = parseTglID(dl);
      const mulaiDate = parseTglID(mulai);
      const dlLewat = !!(dlDate && dlDate < todayWib);
      const mulaiLewat = !!(mulaiDate && mulaiDate < todayWib);

      // ── Verdict: kolom Status yang utama; tanggal cuma JARING PENGAMAN
      //    untuk kasus Sam lupa mengubah Status setelah tanggal terlewat.
      let verdict, alasan = '';
      if (ALWAYS_RE.test(stRaw)) {
        verdict = 'DIBUKA';                       // Always Active -> abaikan tanggal
      } else if (SOON_RE.test(stRaw)) {
        verdict = 'BELUM DIBUKA';
        if (mulaiLewat) {                          // Sam lupa: program sudah jalan
          verdict = 'SUDAH DITUTUP';
          alasan = 'program sudah mulai ' + mulai;
          console.warn('STATUS BASI: ' + nm + ' Status="' + stRaw + '" tapi Tanggal Mulai ' + mulai + ' sudah lewat -> dianggap SUDAH DITUTUP. Perbaiki kolom Status di sheet PROGRAM.');
        }
      } else if (CLOSED_RE.test(stRaw)) {
        verdict = 'SUDAH DITUTUP';
      } else if (OPEN_RE.test(stRaw)) {
        verdict = 'DIBUKA';
        if (dlLewat) {                             // Sam lupa: deadline sudah terlewat
          verdict = 'SUDAH DITUTUP';
          alasan = 'deadline daftar ' + dl + ' sudah lewat';
          console.warn('STATUS BASI: ' + nm + ' Status="' + stRaw + '" tapi Deadline Daftar ' + dl + ' sudah lewat -> dianggap SUDAH DITUTUP. Perbaiki kolom Status/Deadline di sheet PROGRAM.');
        } else if (!dlDate && mulaiLewat) {         // tanpa deadline: pakai tanggal mulai
          verdict = 'SUDAH DITUTUP';
          alasan = 'program sudah mulai ' + mulai;
          console.warn('STATUS BASI: ' + nm + ' Status="' + stRaw + '" tanpa Deadline, tapi Tanggal Mulai ' + mulai + ' sudah lewat -> dianggap SUDAH DITUTUP.');
        }
      } else {
        verdict = 'TIDAK JELAS';                   // di luar dropdown -> jangan menebak
        console.warn('STATUS TIDAK DIKENALI: ' + nm + ' Status="' + stRaw + '". Isi kolom Status dengan salah satu: Active / Coming Soon / Closed / Always Active.');
      }

      let out = verdict === 'TIDAK JELAS'
        ? `${nm}: STATUS PENDAFTARAN TIDAK JELAS - jangan menyatakan buka/tutup, jawab [UNKNOWN] untuk status`
        : `${nm}: PENDAFTARAN ${verdict}${alasan ? ' (' + alasan + ')' : ''}`;

      if (hasBatch) out += `, ${batch}`;
      if (mulai) out += `, Program mulai ${mulai}`;
      if (dl) out += `, Deadline daftar ${dl}`;
      if (kuota) out += `, Kuota ${kuota}`;
      return out;
    });
    parts.push('STATUS & BATCH (sumber resmi & PALING TINGGI - menang atas FAQ. PENDAFTARAN DIBUKA / BELUM DIBUKA / SUDAH DITUTUP di sini FINAL, jangan disimpulkan ulang dari tanggal; program/batch yang tidak ada di sini = tidak ada, jangan dikarang):\n' + lines.join('\n'));
  }

  // Pemetaan program -> kelas (selalu, kecil)
  parts.push('PEMETAAN PROGRAM: Junior=SD6/SMP1 | Intermediate=SMP2/SMP3 | Seniors=SMA kelas 12 | Mock Interview=semua siswa. SMA 10/11 belum ada program.');

  // HARGA (kondisional) -- dari PROGRAM
  if ((flags.askingPrice || flags.wantsToRegister || askingProgramDetail) && prog.length) {
    const lines = prog.map(r => `${val(r, 'Nama Program')}: ${val(r, 'Harga') || 'tidak tertulis'}${val(r, 'Pembayaran') ? ' (' + clip(val(r, 'Pembayaran'), 90) + ')' : ''}${val(r, 'Catatan') ? ' - ' + clip(val(r, 'Catatan'), 70) : ''}`);
    parts.push('HARGA (sebut hanya sesuai ATURAN HARGA di system; ikut status batch):\n' + lines.join('\n'));
  }

  // SYARAT (kondisional) -- dari PROGRAM
  if (askingSyarat && prog.length) {
    const lines = prog.map(r => `${val(r, 'Nama Program')}: Syarat: ${clip(val(r, 'Syarat Umum'), 180)}${val(r, 'Dokumen yang Perlu Disiapkan', 'Dokumen') ? ' | Dokumen: ' + clip(val(r, 'Dokumen yang Perlu Disiapkan', 'Dokumen'), 150) : ''}`);
    parts.push('SYARAT:\n' + lines.join('\n'));
  }

  // PROGRAM detail (kondisional)
  if (askingProgramDetail && prog.length) {
    const lines = prog.map(r => `${val(r, 'Nama Program')}: ${clip(val(r, 'Deskripsi'), 170)} | Target: ${clip(val(r, 'Target Peserta'), 90)} | Durasi: ${clip(val(r, 'Durasi'), 60)} | Format: ${clip(val(r, 'Format'), 60)}`);
    parts.push('PROGRAM (detail):\n' + lines.join('\n'));
  }

  // TENTANG SAM (kondisional) -- dari ABOUT_SAM
  if (askingAboutSam) {
    const about = grab('Read ABOUT Data');
    if (about.length) parts.push('TENTANG SAM & THE SCHOLARS:\n' + about.map(r => `${val(r, 'Aspek')}: ${clip(val(r, 'Detail'), 160)}`).join('\n'));
  }

  // LINK AKTIF (selalu) -- nama saja; URL disisipkan sistem saat [SEND_GFORM]
  const links = grab('Read LINKS Data');
  if (links.length) {
    const activeRows = links.filter(r => /aktif|active|on|ya/i.test(val(r, 'Status')));
    const active = activeRows.map(r => {
      const nm = val(r, 'Nama Link');
      const ds = clip(val(r, 'Deskripsi'), 80);
      return nm ? (ds ? `${nm} \u2014 ${ds}` : nm) : '';
    }).filter(Boolean);
    if (active.length) {
      const sample = val(activeRows[0], 'Nama Link') || 'Nama Link';
      parts.push('LINK AKTIF (saat [SEND_GFORM] WAJIB sebut Nama Link PERSIS, mis. [SEND_GFORM: ' + sample + ']):\n- ' + active.join('\n- '));
    }
  }

  const data_context = parts.join('\n\n');

  // ---------- FAQ lexical retrieval ----------
  const faq = grab('Read FAQ').filter(r => r.Pertanyaan && r.Jawaban);
  const STOP = new Set(['yang','untuk','dan','di','ke','dari','itu','ini','apa','apakah','bisa','kah','ya','yaa','kak','min','dong','sih','kok','aja','ada','gimana','bagaimana','saya','aku','nya','kalau','atau','juga','sudah','belum','mau','dengan','pada','adalah','kira','tolong','mohon','halo','hai','permisi','terima','kasih','sama','buat','soal','tentang','nih','ngga','gak','engga','tidak','dll','dsb','ga','ikut','harus','nanti','dimana','banget','seperti','pakai','punya','lagi','deh','yg','utk','sm','jd','udah','blm']);
  const GROUPS = [
    ['biaya','harga','bayar','tarif','pembayaran','cicil','cicilan','nyicil','nyicilnya','dicicil','ngecicil','dp','mahal','murah','fee','uang','dibayar','bayarnya','investasi','gratis'],
    ['daftar','pendaftaran','registrasi','enroll','gabung','join','mendaftar','ndaftar','apply'],
    ['jadwal','kapan','mulai','periode','angkatan','dibuka'],
    ['syarat','persyaratan','kriteria','ketentuan','requirement'],
    ['beasiswa','scholarship','asean','uob','cli','capitaland','moe','funded'],
    ['program','kelas','junior','intermediate','senior','seniors','jenjang'],
    ['interview','wawancara','mock'],
    ['essay','esai','karangan'],
    ['alumni','lulus','berhasil','diterima','keterima','sukses'],
    ['anak','anaku','anakku','putra','putri','murid','siswa'],
    ['singapura','singapore','sg'],
    ['tinggal','kehidupan','asrama','akomodasi','hidup'],
    ['kuota','slot','penuh','kursi','sisa'],
    ['mengajar','pengajar','guru','mentor','tutor','ngajar'],
  ];
  const SYN = {}; for (const g of GROUPS) for (const w of g) SYN[w] = g[0];
  const stem = (t) => { let w = t; for (const s of ['nya','kah','lah','kan','an','i']) if (w.length - s.length >= 4 && w.endsWith(s)) { w = w.slice(0, -s.length); break; } for (const p of ['meng','meny','mem','men','peng','peny','pem','pen','ber','ter','di','se','ke','me','pe']) if (w.length - p.length >= 4 && w.startsWith(p)) { w = w.slice(p.length); break; } return w; };
  const tok = (s) => (s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean).filter(t => !STOP.has(t)).map(t => { const a = SYN[t]; if (a) return a; const st = stem(t); return SYN[st] || st; }).filter(t => t.length >= 2 && !STOP.has(t));
  const docs = faq.map(r => ({ row: r, toks: tok(r.Pertanyaan) }));
  const Nn = docs.length, df = {};
  for (const dd of docs) for (const t of new Set(dd.toks)) df[t] = (df[t] || 0) + 1;
  const idf = (t) => Math.log((Nn + 1) / ((df[t] || 0) + 1)) + 1;
  const boost = {};
  if (flags.askingPrice || flags.discussingProgram) boost['Program & Biaya'] = 1.25;
  if (flags.askingBatch) boost['Batch & Jadwal'] = 1.30;
  if (flags.wantsToRegister) boost['Seleksi & Proses Daftar'] = 1.20;
  const qToks = [...new Set(tok(query))];
  let faq_context = '';
  if (qToks.length && docs.length) {
    const scored = docs.map(dd => { const dset = new Set(dd.toks); let s = 0, m = 0; for (const t of qToks) if (dset.has(t)) { s += idf(t); m++; } s *= (boost[dd.row.Kategori] || 1.0); return { row: dd.row, score: s, matched: m }; }).sort((a, b) => b.score - a.score);
    const top = scored[0];
    const FLOOR = 2.5, needCov = qToks.length >= 3 ? 2 : 1;
    if (top.score >= FLOOR && top.matched >= needCov) {
      const kept = scored.filter(x => x.score >= 0.45 * top.score && x.matched >= 1).slice(0, 4);
      faq_context = kept.map(x => `Q: ${x.row.Pertanyaan}\nA: ${x.row.Jawaban}`).join('\n\n');
    }
  }

  if (sheetIssues.length) {
    console.error('RINGKASAN MASALAH SHEET pesan ini: ' + sheetIssues.join(' | '));
  }

  return [{ json: { ...pre, faq_context, data_context, sheet_issues: sheetIssues, sheet_debug: sheetDebug }, pairedItem: { item: 0 } }];
} catch (e) {
  const msg = (e && e.message) ? e.message : String(e);
  console.error('FAQ RETRIEVE GAGAL TOTAL: ' + msg);
  const pre = ($('Preprocess - Context Detection').first() || { json: {} }).json || {};
  return [{ json: { ...pre, faq_context: '', data_context: 'PERINGATAN SISTEM: DATABASE TIDAK TERBACA untuk pesan ini. Ini gangguan teknis, BUKAN berarti datanya tidak ada. DILARANG menyatakan program/batch/harga/jadwal tidak ada -> jawab [UNKNOWN] untuk semua pertanyaan fakta. Jangan sebut adanya gangguan sistem ke user.', sheet_issues: ['FAQ Retrieve gagal total: ' + msg], sheet_debug: { 'FAQ Retrieve': 'GAGAL TOTAL — ' + msg }, faq_error: String(e) }, pairedItem: { item: 0 } }];
}

