// (URL yang bahkan tidak terdaftar di LINKS). Filter di bawah menjadikan tab LINKS
// satu-satunya gerbang: URL yang TIDAK terdaftar, atau terdaftar tapi TIDAK aktif,
// dibuang sebelum pesan dikirim.
const LINK_CLOSED_REPLY = 'Untuk linknya saya belum bisa kasih yaa, pendaftarannya lagi tidak dibuka. Kalau mau tanya-tanya lebih lanjut, bisa ngobrol langsung sama Sam yaa, tinggal ketik "mau ngomong sama Sam".';
const LINK_UNVERIFIED_REPLY = 'Untuk linknya saya cek dulu yaa. Kalau mau lebih cepat, bisa ngobrol langsung sama Sam, tinggal ketik "mau ngomong sama Sam".';

// Dicek CLOSED dulu: "Nonaktif" mengandung "aktif", jadi kalau OPEN dicek duluan
// baris nonaktif salah terbaca sebagai aktif.
const LINK_CLOSED_RE = /(closed|close|tutup|ditutup|nonaktif|non\s*-?\s*aktif|inactive|expired|kadaluarsa|kedaluwarsa|selesai|\boff\b)/i;
const LINK_ACTIVE_RE = /(aktif|active|\bon\b|\bya\b|\byes\b)/i;
const isLinkActive = (st) => { const s = String(st || ''); return !LINK_CLOSED_RE.test(s) && LINK_ACTIVE_RE.test(s); };

// Read LINKS Data ber-executeOnce: kalau node ini jalan di run kedua (debounce),
// referensi run saat ini kosong walau datanya sudah terambil di run pertama.
// Tanpa fallback ini guard akan memblokir link yang sebenarnya sah.
const pullLinks = () => {
  const tryPull = (useFirstRun) => {
    try {
      const ref = $('Read LINKS Data');
      const items = useFirstRun ? ref.all(0, 0) : ref.all();
      return (items || []).map(i => i.json).filter(Boolean);
    } catch (e) { return null; }
  };
  const now = tryPull(false);
  if (now && now.length) return now;
  const first = tryPull(true);
  if (first && first.length) {
    console.warn('SAFETY NET LINK: LINKS kosong di run ini, dipakai hasil run pertama. ' + first.length + ' baris.');
    return first;
  }
  return [];
};

const linkRowsGuard = pullLinks();
const linksReadOk = linkRowsGuard.length > 0;
if (!linksReadOk) console.error('SAFETY NET LINK: tab LINKS tidak terbaca - semua URL diblokir demi aman.');

// Samakan bentuk URL sebelum dibandingkan: buang tanda baca penutup & slash akhir.
const normUrl = (u) => String(u || '').trim().toLowerCase()
  .replace(/[)\]\.,;:!?"'\u00bb]+$/g, '')
  .replace(/\/+$/, '');

const activeUrlSet = new Set();
const knownUrlSet = new Set();
for (const r of linkRowsGuard) {
  const u = normUrl(r['URL']);
  if (!u) continue;
  knownUrlSet.add(u);
  if (isLinkActive(r['Status'])) activeUrlSet.add(u);
}

const GUARD_URL_RE = /https?:\/\/[^\s)]+/g;
const foundUrls = cleanOutput.match(GUARD_URL_RE) || [];
const blockedUrls = [];
for (const raw of foundUrls) {
  const n = normUrl(raw);
  if (linksReadOk && activeUrlSet.has(n)) continue;
  blockedUrls.push(raw);
  console.warn('SAFETY NET LINK: URL ditolak -> ' + raw + (knownUrlSet.has(n) ? ' (terdaftar di LINKS tapi TIDAK aktif)' : ' (TIDAK terdaftar di LINKS)'));
}

let linkBlocked = false;
let linkReplyAdded = false;
if (blockedUrls.length) {
  const beforeLink = cleanOutput;
  const hasBlocked = (s) => blockedUrls.some(u => s.includes(u));
  const DROP_L = '\x02';

  // Buang HANYA kalimat yang memuat URL terlarang; kalimat lain dipertahankan.
  const keptLines = cleanOutput
    .split('\n')
    .map(line => {
      const t = line.trim();
      if (!t) return '';
      const k = t
        .split(/(?<=[.!?])\s+/)
        .filter(s => !hasBlocked(s))
        .join(' ')
        .replace(/\s{2,}/g, ' ')
        .trim();
      return k || DROP_L;
    })
    .filter(l => l !== DROP_L);

  // URL sering ditulis di baris sendiri sesudah kalimat pengantar ("daftar di sini yaa:").
  // Tanpa ini pengantarnya menggantung tanpa link.
  let kept = keptLines
    .join('\n')
    .split('\n')
    .filter(l => !/\b(link|daftar|sini|berikut|form)\b[^\n]*[:\uff1a]\s*$/i.test(l.trim()))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const reply = linksReadOk ? LINK_CLOSED_REPLY : LINK_UNVERIFIED_REPLY;
  cleanOutput = kept ? kept + '\n\n' + reply : reply;
  linkBlocked = true;
  linkReplyAdded = true;

  console.warn('SAFETY NET LINK aktif. Diblokir: ' + blockedUrls.join(' | '));
  console.warn('  sebelum:', beforeLink);
  console.warn('  sesudah:', cleanOutput);
}

// Fallback [SEND_GFORM] tanpa nama link akan menyisipkan link pendaftaran default.
// Kalau URL barusan diblokir, itu berarti mengganti link yang ditolak dengan link
// lain yang tidak diminta user - justru menyesatkan. Kalau AI menyebut nama link
// secara eksplisit, resolusi normal tetap jalan (dan tetap disaring status aktif).
if (linkBlocked && !gformLinkName) {
  isSendGForm = false;
  console.warn('SAFETY NET LINK: fallback SEND_GFORM dimatikan (tidak ada nama link eksplisit).');
}

cleanOutput = cleanOutput.replace(/(^|\n)([a-z])/g, (m, p1, p2) => p1 + p2.toUpperCase());

// ── FALLBACK: jika cleanOutput tetap kosong (AI tidak menghasilkan output) ──
if (!cleanOutput || cleanOutput.trim() === '') {
  console.warn('⚠️ cleanOutput kosong! Menggunakan fallback.');
  if (isUnknown) {
    cleanOutput = 'Maaf yaa, untuk pertanyaan ini saya belum punya jawabannya. Nanti saya cari tahu dan kabari lewat sini ya!';
  } else {
    cleanOutput = 'Maaf, terjadi kesalahan. Coba tanyakan ulang yaa.';
  }
}

// ── RESOLVE & INJECT GFORM LINK (inline, data-driven) ───────────
if (isSendGForm) {
  let linkRows = [];
  try {
    linkRows = $('Read LINKS Data').all().map(i => i.json);
  } catch (e) {
    console.warn('⚠️ Tidak bisa baca node Read LINKS Data:', e.message);
  }

  const normL = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  // Pakai helper yang sama dengan SAFETY NET LINK: regex lama meloloskan
  // "Nonaktif" (mengandung "aktif") dan "Coming Soon" tidak, tapi keduanya
  // harus konsisten dengan gerbang di atas.
  const activeRows = linkRows.filter(r => isLinkActive(r['Status']));

  let match = null;
  const rq = normL(gformLinkName);
  if (rq) {
    match = activeRows.find(r => normL(r['Nama Link']) === rq)
         || activeRows.find(r => { const n = normL(r['Nama Link']); return n && (n.includes(rq) || rq.includes(n)); });
  }
  // AI tidak menyebut nama link -> default ke pendaftaran batch reguler
  if (!match && !rq) {
    match = activeRows.find(r => /pendaftaran batch/i.test(String(r['Nama Link'] || '')))
         || activeRows.find(r => /gform|pendaftaran/i.test(String(r['Nama Link'] || '')));
  }

  if (match && match['URL']) {
    gformLinkName = match['Nama Link'];
    const url = String(match['URL']).trim();

    const linkMeta = `${match['Nama Link'] || ''} ${match['Deskripsi'] || ''}`.toLowerCase();
    const isWaChannel =
      /whatsapp\.com\/channel\//i.test(url) ||
      /chat\.whatsapp\.com\//i.test(url) ||
      /channel|komunitas|wa\s*channel/i.test(linkMeta);

    if (!cleanOutput.includes(url)) {
      cleanOutput = isWaChannel
        ? `${cleanOutput}\n\n👉 ${url}`
        : `${cleanOutput}\n\n👉 ${url}\n\nKalau ada yang masih kurang jelas, bisa ngobrol langsung sama Sam yaa. tinggal ketik "mau ngomong sama Sam".`;
    }
    console.log('✅ Link injected inline:', match['Nama Link'], url, isWaChannel ? '(WA channel - tanpa imbuhan)' : '');
  } else {
    console.warn('⚠️ SEND_GFORM aktif tapi link tidak ditemukan/tidak aktif di LINKS. linkName=', gformLinkName || '(kosong)');
    // User memang minta link, tapi barisnya tidak ada atau statusnya bukan aktif.
    // Jangan diam saja - jujur bilang linknya belum bisa dikasih dan arahkan ke Sam.
    if (!linkReplyAdded) {
      cleanOutput = (cleanOutput + '\n\n' + LINK_CLOSED_REPLY).trim();
      linkReplyAdded = true;
    }
  }
}

// ── LOGGING ───────────────────────────────────────────────────
if (isSendGForm)   console.log('📋 SEND_GFORM tag detected');
if (isMockBooking) console.log('📅 MOCK_INTERVIEW_BOOKING detected:', JSON.stringify(mockBookingData));
if (isUnknown)     console.log('❓ UNKNOWN tag detected');

// ── RETURN ──────────────────────────────────────────────────
return [{
  json: {
    ...chatCounter,
    ...preprocess,
    ...item.json, // overwrite dengan data terbaru jika ada konflik
    cleanOutput,
    transferBlocked,
    linkBlocked,
    blockedUrls,
    isSendGForm,
    gformLinkName,
    isMockBooking,
    mockBookingData,
    isUnknown,
    isPendaftaran,
    pendaftaranData,
    isDataComplete,
    dataComplete,
    isTalkToSam,
    nama:    pendaftaranData.nama    || dataComplete.nama    || mockBookingData.nama || '',
    program: pendaftaranData.program || dataComplete.program || 'Mock Interview',
    needs_unknown: isUnknown ? 'true' : 'false',
    can_record_to_sheet: isMockBooking || isPendaftaran || isDataComplete,
    original_message: originalMessage,
    is_new_user: isNewUser,
    kelas_anak_merged: mergedKelas,
    program_interest_merged: mergedProgram,
    kelas_changed: kelasChanged,
  }
}];

// Pilih link GForm dari sheet LINKS sesuai nama yang diminta AI (data-driven)
const rows = $('Query LINKS for GForm').all().map(i => i.json);
const proc = $('Process All').first().json;
const phone = $('Chat Counter').first().json.user_wa || proc.user_wa || '';
const requested = String(proc.gformLinkName || '').trim();

const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const activeRows = rows.filter(r => /aktif|active|on|ya/i.test(String(r['Status'] || '')));

let match = null;
if (requested) {
  const rq = norm(requested);
  match = activeRows.find(r => norm(r['Nama Link']) === rq)
       || activeRows.find(r => { const n = norm(r['Nama Link']); return n && (n.includes(rq) || rq.includes(n)); });
}

if (match && match['URL']) {
  const desc = String(match['Deskripsi'] || '').trim();
  const intro = desc
    ? `Berikut ${desc.charAt(0).toLowerCase() + desc.slice(1)}`
    : `Berikut link ${match['Nama Link']}`;
  const message = `Haii! 😊 ${intro} ya:\n\n👉 ${match['URL']}\n\nSilakan diisi yaa, nanti tim kami follow up setelah form terisi. Ada yang mau ditanyain dulu sebelum isi? Santai aja tanya ke sini! 🙌`;
  console.log('✅ GForm link resolved:', match['Nama Link']);
  return [{ json: { ...proc, gformResolved: true, gformUrl: match['URL'], gformLinkName: match['Nama Link'], gformDesc: desc, phone, message } }];
}

// ── FALLBACK: nama kosong / tidak cocok -> tanya ulang link mana ──
const formRows = activeRows.filter(r => /gform|pendaftaran|mock/i.test(String(r['Nama Link'] || '')));
const listRows = formRows.length ? formRows : activeRows;
const opts = listRows.map(r => {
  const dsc = String(r['Deskripsi'] || '').trim();
  return dsc ? `• ${r['Nama Link']} (${dsc})` : `• ${r['Nama Link']}`;
}).join('\n');
const reason = requested ? `nama link "${requested}" tidak ketemu di LINKS` : 'AI tidak menyertakan nama link';
console.warn('⚠️ Pick GForm Link fallback (tanya ulang):', reason);
const message = opts
  ? `Boleh dibantu kirim link-nya 😊 Yang dimaksud yang mana ya:\n${opts}\n\nTinggal sebut salah satu, nanti langsung saya kirimkan.`
  : 'Boleh dibantu, link mana yang mau dikirim ya? Sebutkan program/keperluannya, nanti saya kirimkan.';
return [{ json: { ...proc, gformResolved: false, gformUrl: '', gformLinkName: requested, phone, message } }];

// Rate Limiter: cegah spam (maks 5 pesan per menit per user)
const input = $input.first().json;
const userWa = $('Resolve User Row').first().json.resolved_key;
const now = Date.now();

// Global store menggunakan $workflow static data
const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};

const userKey = `rl_${userWa}`;
const windowMs = 60000; // 1 menit
const maxMessages = 5;

if (!rateLimits[userKey]) {
  rateLimits[userKey] = { count: 1, windowStart: now };
} else {
  const elapsed = now - rateLimits[userKey].windowStart;
  if (elapsed > windowMs) {
    // Reset window baru
    rateLimits[userKey] = { count: 1, windowStart: now };
  } else {
    rateLimits[userKey].count++;
  }
}

staticData.rateLimits = rateLimits;

const isRateLimited = rateLimits[userKey].count > maxMessages;

if (isRateLimited) {
  console.log(`⛔ RATE LIMITED: ${userWa} sudah ${rateLimits[userKey].count} pesan dalam 1 menit`);
  return [];
}

console.log(`✅ RATE OK: ${userWa} pesan ke-${rateLimits[userKey].count}`);
return [$input.first()];

// ====================================================================
// NODE: Resolve User Row (BARU di V4)
// Identitas user: No WA (phone) = kunci PRIMER, lid = backup.
// Menghilangkan bug fallback rows[0] / match dengan kunci kosong
// yang menyebabkan data user tertukar antar row (kasus Vivipoh/DSS).
// ====================================================================
const cc = $('Chat Counter').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const phone = digits(cc.user_phone);
const lid = digits(cc.user_lid);

if (!phone && !lid) {
  // throw agar tertangkap Error Workflow (VIRA Error Notifier) -> admin dapat notif,
  // bukan silent drop.
  throw new Error('Identitas user kosong (phone & lid tidak ada) - payload webhook tidak dikenal: ' + JSON.stringify(cc.body?.from ?? null));
}

let rows = [];
try {
  rows = $('Read User STATS').all()
    .map(i => i.json)
    .filter(r => r && Object.keys(r).length > 0);
} catch (e) {
  console.warn('⚠️ Read User STATS tidak terbaca:', e.message);
}

// Primer: No WA == phone. Backup: kolom lid == lid.
// Terakhir: No WA == lid (row lama yang tersimpan pakai identitas lid).
let row = null;
if (phone) {
  row = rows.find(r => digits(r['No WA']) === phone) || null;
}
if (!row && lid) {
  row = rows.find(r => digits(r['lid']) === lid)
     || rows.find(r => digits(r['No WA']) === lid)
     || null;
}
// PENTING: tidak ada fallback rows[0]. Tidak ketemu = user baru.

const resolvedKey = row ? String(row['No WA']).trim() : (phone || lid);
const greetingSent = row ? String(row['greeting_sent'] || '').trim().toUpperCase() : '';

console.log(`🔑 resolved_key=${resolvedKey} | row_found=${!!row} | greeting=${greetingSent}`);

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    row_found: !!row,
    bot_mode: row ? String(row['bot_mode'] || '').trim().toUpperCase() : '',
    greeting_sent: greetingSent,
    is_new_user: !row || greetingSent !== 'Y',
    buffer_done_ts: Number(row ? (row['buffer_done_ts'] || 0) : 0) || 0,
    kelas_anak: row ? String(row['kelas_anak'] || '').trim() : '',
    kelas_anak_ts: Number(row ? (row['kelas_anak_ts'] || 0) : 0) || 0,
    program_interest: row ? String(row['program_interest'] || '').trim() : '',
    counter_db: Number(row ? (row['Counter'] || 0) : 0) || 0
  }
}];
